        for (int i = 0; i < s.Length; i++) {
            char c = s[i];

            // If operand, add to result
            if ((c >= 'a' && c <= 'z') ||
                (c >= 'A' && c <= 'Z') ||
                (c >= '0' && c <= '9'))
                res += c;

            // If '(', push to stack
            else if (c == '(')
                st.Push('(');

            // If ')', pop until '('
            else if (c == ')') {
                while (st.Count > 0 && st.Peek() != '(') {
                    res += st.Pop();
